    NO_HIT: 'NO_HIT',
    NO_CONNECTED_PATH: 'NO_CONNECTED_PATH',
    AMBIGUOUS_ROUTE: 'AMBIGUOUS_ROUTE',
    ROUTE_SEARCH_TRUNCATED: 'ROUTE_SEARCH_TRUNCATED',
    UNSUPPORTED_GEOMETRY: 'UNSUPPORTED_GEOMETRY',
    NON_FINITE_GEOMETRY: 'NON_FINITE_GEOMETRY',
